CREATE TABLE Catalogo_Alergenos (
    idAlergeno INT AUTO_INCREMENT NOT NULL,
    NombreAlergeno VARCHAR(255),
    CONSTRAINT Catalogo_Alergenos_pk PRIMARY KEY (idAlergeno)
);

CREATE TABLE Frecuencia_Alimentos (
    id_Alimentos INT AUTO_INCREMENT NOT NULL,
    Alimentos VARCHAR(255),
    CONSTRAINT Frecuencia_Alimentos_pk PRIMARY KEY (id_Alimentos)
);

CREATE TABLE FrecuenciaOpciones (
    id_Frecuencia INT AUTO_INCREMENT NOT NULL,
    Nombre_frecuencia VARCHAR(255),
    CONSTRAINT FrecuenciaOpciones_pk PRIMARY KEY (id_Frecuencia)
);
